check_code:
corr={'A':'F','B':'D','C':'E'}
ang={'A':95,'B':52}
ang['C']=180-95-52
DF=17 if {corr['A'],corr['B']}=={'D','F'} else None
E=ang['C'] if corr['C']=='E' else None
opts={'A':('DE',17,'E',33),'B':('DE',17,'F',33),'C':('DF',17,'D',33),'D':('DF',17,'E',33)}
def ok(o):
    s,l,a,v=o
    side_ok=(s=='DF' and l==17)
    ang_ok=(a=='E' and v==E)
    return side_ok and ang_ok
assert ok(opts['D'])
assert not any(ok(opts[k]) for k in 'ABC')

